parameters.jsCode:
const items = $input.all();
const data = items.map(i => i.json);

// Sales KPIs
const salesData = data.filter(d => d._source === 'sales' || d.department === 'sales');
const totalRevenue = salesData.reduce((sum, d) => sum + (Number(d.revenue) || Number(d.amount) || 0), 0);
const totalDeals = salesData.length;
const avgDealSize = totalDeals > 0 ? Math.round(totalRevenue / totalDeals * 100) / 100 : 0;
const closedWon = salesData.filter(d => (d.status || '').toLowerCase() === 'won').length;
const winRate = totalDeals > 0 ? Math.round((closedWon / totalDeals) * 10000) / 100 : 0;

// Marketing KPIs
const marketingData = data.filter(d => d._source === 'marketing' || d.department === 'marketing');
const totalLeads = marketingData.reduce((sum, d) => sum + (Number(d.leads) || 1), 0);
const totalSpend = marketingData.reduce((sum, d) => sum + (Number(d.spend) || Number(d.cost) || 0), 0);
const costPerLead = totalLeads > 0 ? Math.round(totalSpend / totalLeads * 100) / 100 : 0;

// Support KPIs
const supportData = data.filter(d => d._source === 'support' || d.department === 'support');
const totalTickets = supportData.length;
const resolvedTickets = supportData.filter(d => (d.status || '').toLowerCase() === 'resolved').length;
const resolutionRate = totalTickets > 0 ? Math.round((resolvedTickets / totalTickets) * 10000) / 100 : 0;
const avgResponseTime = supportData.reduce((sum, d) => sum + (Number(d.responseTimeHours) || 0), 0) / (totalTickets || 1);

const kpis = {
  date: new Date().toISOString().split('T')[0],
  sales_totalRevenue: totalRevenue,
  sales_totalDeals: totalDeals,
  sales_avgDealSize: avgDealSize,
  sales_winRate: winRate,
  marketing_totalLeads: totalLeads,
  marketing_totalSpend: totalSpend,
  marketing_costPerLead: costPerLead,
  support_totalTickets: totalTickets,
  support_resolutionRate: resolutionRate,
  support_avgResponseTimeHours: Math.round(avgResponseTime * 100) / 100
};

return [{ json: kpis }];

